-- PT119-S3-Q2
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT119-S3-Q2$batch01$ AND q.stimulus=$batch01$Benson: In order to maintain the quality of life in our city, we need to restrict growth. That is why I support the new zoning regulations.Willett: I had heard such arguments ten years ago, and again five years ago. Each time the city council was justified in deciding not to restrict growth. Since there is nothing new in this idea of restricting growth, I oppose the regulations.$batch01$ AND q.prompt=$batch01$Which one of the following most accurately describes a way in which Willett's reasoning is questionable?$batch01$ AND q.correct_choice=$batch01$C$batch01$) THEN RAISE EXCEPTION 'Question changed: PT119-S3-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT119-S3-Q2$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT119-S3-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT119-S3-Q2$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$It presumes that growth is necessarily good without offering support for that position.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT119-S3-Q2 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT119-S3-Q2$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$It is based on attacking Benson personally rather than responding to Benson’s reasoning.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT119-S3-Q2 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT119-S3-Q2$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$It ignores the possibility that new reasons for restricting growth have arisen in the past five years.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT119-S3-Q2 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT119-S3-Q2$batch01$ AND c.letter=$batch01$D$batch01$ AND c.choice_text=$batch01$It fails to take into account the variety of factors that contribute to the quality of life in a city.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT119-S3-Q2 D'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT119-S3-Q2$batch01$ AND c.letter=$batch01$E$batch01$ AND c.choice_text=$batch01$It overlooks the possibility that the city council of ten years ago was poorly qualified to decide on zoning regulations.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT119-S3-Q2 E'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s JOIN lr_explanations e ON e.id=s.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT119-S3-Q2$batch01$ AND e.style IN ('single','standard')) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n JOIN lr_explanations e ON e.id=n.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT119-S3-Q2$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT119-S3-Q2'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT119-S3-Q2$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion (Willett)$batch01$, $batch01$He opposes the new zoning regulations restricting growth.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$Similar arguments for restricting growth arose ten and five years ago, and the council was justified in rejecting them then. Willett says there is nothing new in the idea.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$A familiar *proposal* can have new reasons behind it. Growth might have changed the city's housing, congestion, or infrastructure since the last decision. Even if those earlier councils were right, their decisions do not automatically settle today's case. Willett must assess the present evidence for Benson's quality-of-life claim.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Find the possibility that new circumstances or reasons arose after the earlier decisions.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT119-S3-Q2$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$Willett need not think all growth is good. He can oppose this particular restriction while accepting that some growth has costs. His stated reason is the earlier rejections.$batch01$), ($batch01$B$batch01$, $batch01$Willett does not attack Benson's character. He attacks the age of the proposal and cites past council decisions.$batch01$), ($batch01$C$batch01$, $batch01$The idea of restricting growth can be old while reasons supporting it are new. Changes in the past five years could make today's regulation warranted even though earlier councils rightly rejected earlier restrictions.$batch01$), ($batch01$D$batch01$, $batch01$Many factors may affect quality of life, but Willett does not attempt a full quality-of-life analysis. The flaw in *his* argument is using the oldness of the proposal as if it ruled out new justification.$batch01$), ($batch01$E$batch01$, $batch01$The council ten years ago may have been well qualified and correct in its own circumstances. That still would not decide whether present reasons support new zoning rules.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT119-S3-Q2$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
COMMIT;
